import React, { useRef } from 'react';
import './ProductCarousel.css';

const ProductCarousel = ({ categoryName, products, onAddToCart }) => {
  const scrollContainerRef = useRef(null);

  const scroll = (direction) => {
    if (scrollContainerRef.current) {
      const scrollAmount = 300;
      if (direction === 'left') {
        scrollContainerRef.current.scrollBy({ left: -scrollAmount, behavior: 'smooth' });
      } else {
        scrollContainerRef.current.scrollBy({ left: scrollAmount, behavior: 'smooth' });
      }
    }
  };

  return (
    <div className="category-section">
      <h2 className="category-title">📦 {categoryName}</h2>
      
      <div className="carousel-container">
        <button 
          className="carousel-btn carousel-btn-left" 
          onClick={() => scroll('left')}
          aria-label="Scroll left"
        >
          ⬅️
        </button>

        <div className="products-carousel" ref={scrollContainerRef}>
          {products.map((product) => (
            <div key={product.id} className="product-card-carousel">
              <div className="product-image-container">
                <img 
                  src={product.image_url} 
                  alt={product.name}
                  className="product-image"
                  onError={(e) => {
                    e.target.src = 'https://via.placeholder.com/200x200?text=Sem+Imagem';
                  }}
                />
                {product.estoque === 0 && (
                  <div className="estoque-badge out-of-stock">ESGOTADO</div>
                )}
                {product.estoque > 0 && product.estoque < 10 && (
                  <div className="estoque-badge low-stock">BAIXO</div>
                )}
              </div>

              <div className="product-info">
                <h3 className="product-name">{product.name}</h3>
                <p className="product-price">
                  R$ {parseFloat(product.price).toFixed(2)}
                </p>
                <p className="product-unit">{product.unit}</p>
              </div>

              <button
                className={`btn-add-to-cart ${product.estoque === 0 ? 'disabled' : ''}`}
                onClick={() => onAddToCart(product)}
                disabled={product.estoque === 0}
              >
                {product.estoque === 0 ? 'Indisponível' : 'Adicionar'}
              </button>
            </div>
          ))}
        </div>

        <button 
          className="carousel-btn carousel-btn-right" 
          onClick={() => scroll('right')}
          aria-label="Scroll right"
        >
          ➡️
        </button>
      </div>
    </div>
  );
};

export default ProductCarousel;
